package user

import "errors"

// User is an account.
type User struct{ Name string }

// New checks name and returns its User.
func New(name string) (User, error) {
	if name == "" {
		return User{}, errors.New("empty name")
	}
	if len(name) > 32 {
		return User{}, errors.New("name too long")
	}
	return User{Name: name}, nil
}

